# Alter Table lookup_value
#   drop index value_type_parent_unique;

SET
@lookupTypeId = (SELECT lookup_type_id FROM lookup_type WHERE lookup_type_code = 'LOCATION_STATUS');
delete from lookup_value where lookup_type_id = @lookupTypeId
                          and lookup_value = 'Customer Unresponsive' and sort_seq = 50;


ALTER TABLE lookup_value
	ADD CONSTRAINT value_type_parent_unique
	UNIQUE  (lookup_value, lookup_type_id, parent_lookup_value_id);

update lookup_value set parent_lookup_value_id = 0 where parent_lookup_value_id is null;
Alter table qto.lookup_value alter parent_lookup_value_id set default 0;

